  useEffect(()=>{const checkSchedule=()=>{const parts=new Intl.DateTimeFormat('en-CA',{timeZone:timezone,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date());const value=(type:string)=>parts.find(part=>part.type===type)?.value||'00';const day=`${value('year')}-${value('month')}-${value('day')}`,time=`${value('hour')}:${value('minute')}`;const reminders:{time:string;title:string;message:string}[]=[{time:'11:50',title:'Lunchtime, Champs!',message:'It’s lunchtime, Champs! Enjoy your lunch and have a lovely break!'},{time:'14:20',title:'Snack time, Champs!',message:'It’s snack time, Champs! Let’s recharge with a tasty little break!'},{time:'16:35',title:'Time to go home, Champs!',message:'It’s time to go home, Champs! You did a wonderful job today.'}];const reminder=reminders.find(item=>item.time===time);if(!reminder)return;const key=`ezgili-routine-reminders:${classroomId}:${day}`;try{const sent=JSON.parse(localStorage.getItem(key)||'[]') as string[];if(sent.includes(time))return;localStorage.setItem(key,JSON.stringify([...sent,time]));}catch{}setActivityNotice({title:reminder.title,message:reminder.message});};checkSchedule();const interval=window.setInterval(checkSchedule,5000);return()=>window.clearInterval(interval);},[timezone,classroomId]);
  useEffect(()=>{try{const parsed=JSON.parse(localStorage.getItem('ezgili-classroom-themes')||'{}') as Record<string,string>;const valid=Object.fromEntries(Object.entries(parsed).filter(([id,value])=>classrooms.some(c=>c.id===id)&&classroomThemeOptions.some(option=>option.id===value)));setClassroomThemes(valid);}catch{}},[]);
  useEffect(()=>{if(classroomId) getPeriodReport(classroomId,period==='This month'?'month':'week').then(setReportData).catch(()=>notify('Could not load this report.'));},[classroomId,period,earned]);
  const filtered=useMemo(()=>students.filter(s=>s.name.toLowerCase().includes(query.toLowerCase())),[students,query]);
  const visibleStudents=rosterCollapsed?filtered.slice(0,Math.ceil(filtered.length/2)):filtered;
  const topChamps=useMemo(()=>{const source=reportData?.rows||students.map(student=>({id:student.id,display_name:student.name,avatar:student.avatar,total:total(student)}));return [...source].map(row=>({id:String(row.id),name:String(row.display_name),avatar:('avatar_key' in row?avatarMap[String(row.avatar_key)]:String(row.avatar))||'🌟',points:Number(row.total||0)})).sort((a,b)=>b.points-a.points||a.name.localeCompare(b.name)).slice(0,6);},[reportData,students]);
  const notify=(msg:string)=>{setToast(msg);setTimeout(()=>setToast(''),2400)};
  const playApplause=()=>{try{const prefs=JSON.parse(localStorage.getItem('ezgili-classroom-fun')||'{}');const mode=prefs.celebrationSound||'applause';if(mode==='silent')return;const context=new window.AudioContext();if(mode==='gentle'){[523.25,659.25,783.99].forEach((frequency,index)=>{const oscillator=context.createOscillator(),gain=context.createGain(),at=context.currentTime+index*.16;oscillator.type='sine';oscillator.frequency.value=frequency;gain.gain.setValueAtTime(.001,at);gain.gain.exponentialRampToValueAtTime(.12,at+.04);gain.gain.exponentialRampToValueAtTime(.001,at+.42);oscillator.connect(gain);gain.connect(context.destination);oscillator.start(at);oscillator.stop(at+.45);});window.setTimeout(()=>{void context.close()},1300);return;}const master=context.createGain();master.gain.value=.38;master.connect(context.destination);const start=context.currentTime;for(let i=0;i<52;i++){const duration=.07+Math.random()*.09,length=Math.ceil(context.sampleRate*duration),buffer=context.createBuffer(1,length,context.sampleRate),samples=buffer.getChannelData(0);for(let j=0;j<length;j++)samples[j]=(Math.random()*2-1)*(1-j/length);const source=context.createBufferSource(),filter=context.createBiquadFilter(),gain=context.createGain(),at=start+.04+Math.random()*1.55;source.buffer=buffer;filter.type='bandpass';filter.frequency.value=850+Math.random()*1250;filter.Q.value=.65;gain.gain.setValueAtTime(.001,at);gain.gain.exponentialRampToValueAtTime(.14+Math.random()*.16,at+.008);gain.gain.exponentialRampToValueAtTime(.001,at+duration);source.connect(filter);filter.connect(gain);gain.connect(master);source.start(at);source.stop(at+duration);}window.setTimeout(()=>{void context.close()},2500);}catch{}}
  const ringSchoolBell=()=>{try{const context=bellAudioRef.current||new window.AudioContext();bellAudioRef.current=context;void context.resume().then(()=>{const master=context.createGain();master.gain.value=.24;master.connect(context.destination);[0,.62,1.24].forEach((offset)=>{[[880,1],[1320,.45],[1760,.2]].forEach(([frequency,volume])=>{const oscillator=context.createOscillator(),gain=context.createGain(),at=context.currentTime+offset;oscillator.type='sine';oscillator.frequency.value=frequency;gain.gain.setValueAtTime(.0001,at);gain.gain.exponentialRampToValueAtTime(volume*.38,at+.018);gain.gain.exponentialRampToValueAtTime(.0001,at+.9);oscillator.connect(gain);gain.connect(master);oscillator.start(at);oscillator.stop(at+.92);});});});}catch{}}
  const startLesson=()=>{const deadline=Date.now()+40*60*1000;lessonDeadlineRef.current=deadline;lessonClassroomRef.current=classroom;setLessonDeadline(deadline);setLessonClassroom(classroom);setLessonClock(Date.now());try{localStorage.setItem('ezgili-lesson-bell',JSON.stringify({deadline,classroom}));}catch{}try{bellAudioRef.current??=new window.AudioContext();void bellAudioRef.current.resume();}catch{}};
  const stopLesson=()=>{lessonDeadlineRef.current=null;lessonClassroomRef.current='';setLessonDeadline(null);setLessonClassroom('');try{localStorage.removeItem('ezgili-lesson-bell');}catch{}};
  const lessonRemaining=lessonDeadline?Math.max(0,Math.ceil((lessonDeadline-lessonClock)/1000)):0;
  const lessonDisplay=`${String(Math.floor(lessonRemaining/60)).padStart(2,'0')}:${String(lessonRemaining%60).padStart(2,'0')}`;
  const popChamp=(student:typeof topChamps[number])=>{setPoppedStudents(previous=>new Set(previous).add(student.id));setCelebrating(student);playApplause();};
  const toggle=(id:string,index:number)=>{const target=students.find(s=>s.id===id); if(!target)return;const checks=target.checks.map((c,i)=>i===index?!c:c);setStudents(prev=>prev.map(s=>s.id===id?{...s,checks}:s));startTransition(async()=>{const previous=saves.current.get(id)||Promise.resolve();const next=previous.catch(()=>undefined).then(()=>saveBehaviorRecord(id,target.groupId,initialData.today,Object.fromEntries(['homework_complete','class_participation','speaking_effort','project_complete','class_readiness','speaking_day_rules'].map((k,i)=>[k,checks[i]]))));saves.current.set(id,next);try{await next;notify('Progress saved');}catch{notify('Could not save. Please try again.');}});};
  const addStudent=()=>{const name=draft.trim();if(!name||!classroomId)return;startTransition(async()=>{try{const row=await createStudent(classroomId,name,avatarChoices[Math.floor(Math.random()*avatarChoices.length)].key);setStudents(prev=>[...prev,mapStudent({...row,criteria:null} as Parameters<typeof mapStudent>[0],prev.length)]);setDraft('');setModal('');notify(`${displayStudentName(name)} added to ${classroom}`);}catch{notify('Could not add student.');}});};
  const scanPhoto=async(event:ChangeEvent<HTMLInputElement>)=>{const file=event.target.files?.[0];if(!file)return;setPhotoError('');setPhotoNames([]);setOcrBusy(true);try{const worker=await createWorker('eng');const result=await worker.recognize(file);await worker.terminate();const names=result.data.text.split(/\n+/).map(line=>line.replace(/^\s*(?:\d+[.)-]?|[-•])\s*/,'').replace(/\s{2,}.*/, '').trim()).filter(line=>line.length>1&&line.length<=100&&!/^(name|student|class|grade|roll|no\.?|list)$/i.test(line));setPhotoNames([...new Set(names)]);if(!names.length)setPhotoError('No names found. Try a clearer, well lit photo of the list.');}catch{setPhotoError('Could not read this image. Try a clear photo with printed or neat handwriting.');}finally{setOcrBusy(false);event.target.value='';}};
  const importPhotoNames=()=>{const names=photoNames.map(n=>n.trim()).filter(Boolean);if(!classroomId||!names.length)return;startTransition(async()=>{try{const rows=await createStudents(classroomId,names);setStudents(prev=>[...prev,...rows.map((r,i)=>mapStudent({...r,criteria:null} as Parameters<typeof mapStudent>[0],prev.length+i))]);setPhotoNames([]);setModal('');notify(`${rows.length} students added to ${classroom}`);}catch(e){setPhotoError(e instanceof Error?e.message:'Could not import names.');}});};
