  const deactivatePrize=(prizeName:string)=>{const prize=(initialData.prizes as Array<{id:string;name:string}>).find(p=>p.name===prizeName);if(!prize)return;startTransition(async()=>{try{await setPrizeActive(prize.id,false);setPrizes(prev=>prev.filter(p=>p!==prizeName));notify('Prize deactivated');}catch{notify('Could not update prize.');}});};
  const draw=()=>{if(!classroomId){notify('Create a classroom first');return;}if(onlyPresent&&presentIds&&!drawStudentId&&!presentIds.length){notify('Everyone is marked away. Change roll call first.');return;}setSpinning(true);drawKey.current??=crypto.randomUUID();const key=drawKey.current;startTransition(async()=>{try{const result=await drawReward({idempotencyKey:key,classroomId,studentId:drawStudentId||undefined,presentIds:onlyPresent&&presentIds&&!drawStudentId?presentIds:undefined});drawKey.current=null;setTimeout(()=>{const row=result as {id?:string;student:string;prize:string;avatar_key:string;drawn_at:string};const display={id:row.id?String(row.id):undefined,name:row.student,prize:row.prize,avatar:avatarMap[row.avatar_key]||'🎉',at:'Just now',bookReturned:false};setDraws(prev=>[display,...prev]);setWinner(display);setSpinning(false);},800);}catch(e){setSpinning(false);notify(e instanceof Error?e.message:'Could not draw a reward.');}});};
